import request from '@/static/js/request'


/**
 * 电表充值
 */
export function ammeterRecharge(param) {
	return new Promise((resolve, reject) => {
		request({
			url: "/app/recharge/ammeter",
			method: "POST",
			data: param,
		}).then((res) => {
			resolve(res);
		}).catch((error) => {
			uni.showToast({
				title: '服务异常.',
				icon: 'none',
				duration: 3000
			});
		})
	})
}


